mapper.select:
SELECT seq, IFNULL(ipaddr, '') AS ipaddr, ipyn, IFNULL(deptnm, '') AS deptnm, IFNULL(usernm, '') AS usernm, IFNULL(pubipaddr, '') AS pubipaddr, IFNULL(etc, '') AS etc
  FROM gw_iplist
 WHERE seq = #{seq}

mapper.update:
UPDATE gw_iplist
   SET deptnm=#{deptnm}, usernm=#{usernm}, pubipaddr=#{pubipaddr}, etc=#{etc}, regid=#{regid}, regip=#{regip}, regdt=NOW(), ipyn=#{ipyn}
 WHERE seq=#{seq}
